/**
 * Every dedicated server the Steam catalogue carried, as of the last full
 * ISteamApps/GetAppList snapshot (Wayback Machine capture, 25 Aug 2025).
 *
 * GENERATED FILE -- do not edit entries by hand.
 *
 * Valve retired the open app list in 2025 and its replacement
 * (IStoreService) only returns apps with store pages, which dedicated
 * server tools do not have -- tested, it finds 12 of these 579. So the
 * complete list ships with GameKeepr as data, the way the game registry
 * does, and the live store search plus the paste-an-appid path pick up
 * anything newer. Regenerate from a fresh full-list source with:
 *   filter: /dedicated server/i or a name ending in "... Server",
 *   minus names ending in "test server".
 */

export interface KnownSteamServer {
  appid: number;
  name: string;
  /**
   * The tool's own Steam client icon (a hash on the community CDN), baked in
   * at generation time: these apps have no store page, so this is the only
   * artwork they have, and fetching it per row would mean 579 live calls.
   */
  icon?: string;
  /**
   * Whether SteamCMD downloads this app with anonymous login, per the
   * community-maintained Valve wiki "Dedicated Servers List" (capture of
   * 2026-08-07). Absent means the wiki does not say -- including three apps
   * whose rows contradicted each other, which are deliberately left unknown
   * rather than guessed. The preflight treats false as a warning, not a
   * refusal: the source is a wiki, and a stale "no" must never block a
   * deploy that would have worked.
   */
  anon?: boolean;
  /**
   * Which builds Steam publishes for this app, from SteamCMD's own app info
   * (api.steamcmd.net, captured on OS_CAPTURE_DATE by
   * scripts/enrich-steam-os.mts — which imports the deploy preflight's own
   * classifier, so this value and the deploy-time judgement cannot drift
   * apart). "windows" means the server runs here through Wine; "none" means
   * not even a Windows build exists. Absent means Steam had no usable app
   * info at capture time — unknown stays unknown. This field informs the
   * catalogue row; the deploy always inspects the app live and decides from
   * that.
   */
  os?: 'linux' | 'windows' | 'both' | 'none';
}

